// Generated by `drift_dev make-migrations`, then extended with data checks
// for each upgrade.
import 'package:drift/drift.dart' hide isNull;
import 'package:drift_dev/api/migrations_native.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:memuki/domain/ids.dart';
import 'package:memuki/domain/preset.dart';
import 'package:memuki/domain/review.dart';
import 'package:memuki/scheduler/schedulers.dart';
import 'package:memuki/services/rebuild_service.dart';
import 'package:memuki/storage/converters.dart';
import 'package:memuki/storage/database.dart';
import 'package:memuki/storage/database_exceptions.dart';
import 'package:memuki/storage/repositories/repositories.dart';
import 'package:memuki/storage/sync/hlc.dart';

import 'generated/schema.dart';

void main() {
  driftRuntimeOptions.dontWarnAboutMultipleDatabases = true;
  final replay = historyReplay(allSchedulers);
  late SchemaVerifier verifier;

  setUpAll(() {
    verifier = SchemaVerifier(GeneratedHelper());
  });

  group('simple database migrations', () {
    // Verifies every schema upgrade without data.
    const versions = GeneratedHelper.versions;
    for (final (i, fromVersion) in versions.indexed) {
      group('from $fromVersion', () {
        for (final toVersion in versions.skip(i + 1)) {
          test('to $toVersion', () async {
            final schema = await verifier.schemaAt(fromVersion);
            final db = MemukiDatabase(
              schema.newConnection(),
              replayHistory: replay,
            );
            await verifier.migrateAndValidate(db, toVersion);
            await db.close();
          });
        }
      });
    }
  });

  test('v1 to v2 stamps existing rows and keeps their data', () async {
    final schema = await verifier.schemaAt(1);
    final collection = CollectionId.generate();
    final deck = DeckId.generate();
    final noteType = NoteTypeId.generate();
    final field = FieldDefinitionId.generate();
    final template = StudyCardTemplateId.generate();
    final note = NoteId.generate();
    final card = StudyCardId.derive(note, template);
    final event = ReviewEventId.generate();
    Uint8List bytes(Object id) => Uint8List.fromList(
      // Every ID type is a UUID string at runtime.
      const IdConverter<String>(_identity).toSql(id as String),
    );

    final raw = schema.rawDatabase;
    raw.execute('INSERT INTO collections VALUES (?, ?)', [
      bytes(collection),
      'Japanese',
    ]);
    raw.execute('INSERT INTO decks VALUES (?, ?, NULL, ?)', [
      bytes(deck),
      bytes(collection),
      'Vocab',
    ]);
    raw.execute('INSERT INTO note_types VALUES (?, ?, ?)', [
      bytes(noteType),
      bytes(collection),
      'Basic',
    ]);
    raw.execute('INSERT INTO field_definitions VALUES (?, ?, 0, ?, ?)', [
      bytes(field),
      bytes(noteType),
      'Front',
      'text',
    ]);
    raw.execute('INSERT INTO study_card_templates VALUES (?, ?, 0, ?)', [
      bytes(template),
      bytes(noteType),
      'Card 1',
    ]);
    raw.execute('INSERT INTO notes VALUES (?, ?, ?, NULL, NULL)', [
      bytes(note),
      bytes(collection),
      bytes(noteType),
    ]);
    raw.execute('INSERT INTO note_fields VALUES (?, ?, ?)', [
      bytes(note),
      bytes(field),
      '猫',
    ]);
    raw.execute('INSERT INTO study_cards VALUES (?, ?, ?, ?, ?)', [
      bytes(card),
      bytes(collection),
      bytes(note),
      bytes(template),
      bytes(deck),
    ]);
    raw.execute(
      'INSERT INTO review_events VALUES '
      "(?, ?, 'review', 1000, 'good', NULL, NULL, NULL, NULL, 'sm2', 1, 1)",
      [bytes(event), bytes(card)],
    );

    final now = DateTime.utc(2026, 10, 29, 12);
    final db = MemukiDatabase(
      schema.newConnection(),
      now: () => now,
      replayHistory: replay,
    );
    addTearDown(db.close);

    final device = await db.select(db.device).getSingle();
    final initial = Hlc(now.millisecondsSinceEpoch, 0, device.node);
    // Later upgrades stamp their own rows after this one.
    expect(device.lastHlc! > initial || device.lastHlc == initial, isTrue);

    final deckRow = await db.select(db.decks).getSingle();
    expect(deckRow.name, 'Vocab');
    expect(deckRow.hlc, initial);
    expect(deckRow.deleted, isFalse);
    expect((await db.select(db.noteFields).getSingle()).value, '猫');
    expect((await db.select(db.noteFields).getSingle()).hlc, initial);
    expect((await db.select(db.reviewEvents).getSingle()).hlc, initial);
    expect(await db.select(db.outbox).get(), isEmpty);

    // The clock continues after the migration's timestamp.
    expect(db.clock.tick() > initial, isTrue);
  });

  test('v3 to v4 gives existing review events a zero UTC offset', () async {
    final schema = await verifier.schemaAt(3);
    final collection = CollectionId.generate();
    final deck = DeckId.generate();
    final noteType = NoteTypeId.generate();
    final template = StudyCardTemplateId.generate();
    final note = NoteId.generate();
    final card = StudyCardId.derive(note, template);
    final event = ReviewEventId.generate();
    Uint8List bytes(Object id) => Uint8List.fromList(
      const IdConverter<String>(_identity).toSql(id as String),
    );
    const hlc = '019a2f0c8a00-0000-0123456789abcdef';

    final raw = schema.rawDatabase;
    raw.execute('INSERT INTO collections (id, name, hlc) VALUES (?, ?, ?)', [
      bytes(collection),
      'Japanese',
      hlc,
    ]);
    raw.execute(
      'INSERT INTO decks (id, collection_id, name, hlc) VALUES (?, ?, ?, ?)',
      [bytes(deck), bytes(collection), 'Vocab', hlc],
    );
    raw.execute(
      'INSERT INTO note_types (id, collection_id, name, hlc) VALUES (?, ?, ?, ?)',
      [bytes(noteType), bytes(collection), 'Basic', hlc],
    );
    raw.execute(
      'INSERT INTO study_card_templates (id, note_type_id, position, name, hlc) '
      'VALUES (?, ?, 0, ?, ?)',
      [bytes(template), bytes(noteType), 'Card 1', hlc],
    );
    raw.execute(
      'INSERT INTO notes (id, collection_id, note_type_id, hlc) '
      'VALUES (?, ?, ?, ?)',
      [bytes(note), bytes(collection), bytes(noteType), hlc],
    );
    raw.execute(
      'INSERT INTO study_cards '
      '(id, collection_id, note_id, template_id, deck_id, hlc) '
      'VALUES (?, ?, ?, ?, ?, ?)',
      [
        bytes(card),
        bytes(collection),
        bytes(note),
        bytes(template),
        bytes(deck),
        hlc,
      ],
    );
    raw.execute(
      'INSERT INTO review_events (id, study_card_id, kind, at, grade, '
      'scheduler_id, scheduler_version, config_version, hlc) '
      "VALUES (?, ?, 'review', 1000, 'good', 'sm2', 1, 1, ?)",
      [bytes(event), bytes(card), hlc],
    );

    final db = MemukiDatabase(schema.newConnection(), replayHistory: replay);
    addTearDown(db.close);
    await verifier.migrateAndValidate(db, 4);

    // Read as SQL, since the current table classes are of a later version.
    final row = await db
        .customSelect('SELECT id, grade, utc_offset FROM review_events')
        .getSingle();
    expect(row.read<Uint8List>('id'), bytes(event));
    expect(row.read<String>('grade'), 'good');
    expect(row.read<int>('utc_offset'), 0);
    // The rebuilt table keeps its append-only trigger.
    await expectLater(
      db.customStatement("UPDATE review_events SET grade = 'again'"),
      throwsA(anything),
    );
  });

  test('v4 to v5 gives each collection a default preset used by all its '
      'decks and events', () async {
    final schema = await verifier.schemaAt(4);
    final collections = [CollectionId.generate(), CollectionId.generate()];
    final root = DeckId.generate();
    final child = DeckId.generate();
    final noteType = NoteTypeId.generate();
    final template = StudyCardTemplateId.generate();
    final note = NoteId.generate();
    final card = StudyCardId.derive(note, template);
    final event = ReviewEventId.generate();
    Uint8List bytes(Object id) => Uint8List.fromList(
      const IdConverter<String>(_identity).toSql(id as String),
    );
    const hlc = '019a2f0c8a00-0000-0123456789abcdef';

    final raw = schema.rawDatabase;
    for (final (i, collection) in collections.indexed) {
      raw.execute('INSERT INTO collections (id, name, hlc) VALUES (?, ?, ?)', [
        bytes(collection),
        'Collection $i',
        hlc,
      ]);
    }
    final japanese = bytes(collections.first);
    raw.execute(
      'INSERT INTO decks (id, collection_id, parent_id, name, hlc) '
      'VALUES (?, ?, NULL, ?, ?), (?, ?, ?, ?, ?)',
      [
        ...[bytes(root), japanese, 'Vocab', hlc],
        ...[bytes(child), japanese, bytes(root), 'N5', hlc],
      ],
    );
    raw.execute(
      'INSERT INTO note_types (id, collection_id, name, hlc) VALUES (?, ?, ?, ?)',
      [bytes(noteType), japanese, 'Basic', hlc],
    );
    raw.execute(
      'INSERT INTO study_card_templates (id, note_type_id, position, name, hlc) '
      'VALUES (?, ?, 0, ?, ?)',
      [bytes(template), bytes(noteType), 'Card 1', hlc],
    );
    raw.execute(
      'INSERT INTO notes (id, collection_id, note_type_id, hlc) '
      'VALUES (?, ?, ?, ?)',
      [bytes(note), japanese, bytes(noteType), hlc],
    );
    raw.execute(
      'INSERT INTO study_cards '
      '(id, collection_id, note_id, template_id, deck_id, hlc) '
      'VALUES (?, ?, ?, ?, ?, ?)',
      [bytes(card), japanese, bytes(note), bytes(template), bytes(child), hlc],
    );
    raw.execute(
      'INSERT INTO review_events (id, study_card_id, kind, at, utc_offset, '
      'grade, scheduler_id, scheduler_version, config_version, hlc) '
      "VALUES (?, ?, 'review', 1000, 540, 'good', 'sm2', 1, 1, ?)",
      [bytes(event), bytes(card), hlc],
    );

    final v5 = MemukiDatabase(schema.newConnection(), replayHistory: replay);
    addTearDown(v5.close);
    await verifier.migrateAndValidate(v5, 5);
    // Read through the repositories after upgrading to the current version,
    // since they use the current tables. Opening turned foreign keys on for
    // the shared connection; upgrades run with them off.
    await v5.customStatement('PRAGMA foreign_keys = OFF');
    final db = MemukiDatabase(schema.newConnection(), replayHistory: replay);
    addTearDown(db.close);
    final repos = Repositories(db);

    final presets = [
      for (final collection in collections)
        await repos.presets.defaultPreset(collection),
    ];
    expect(presets.map((p) => p.name), ['Default', 'Default']);
    expect(presets.first.id, isNot(presets.last.id));
    expect(presets.first.version, PresetVersion(id: presets.first.version.id));
    expect(
      (await repos.presets.presets(collections.first)).single,
      presets.first,
    );
    expect(
      (await repos.collections.collection(collections.first))!.dayStart,
      const Duration(hours: 3),
    );
    expect((await repos.collections.deck(child))!.presetId, isNull);
    expect(await repos.presets.effectivePreset(child), presets.first);

    final history = await repos.reviews.history(card);
    expect(history.single.id, event);
    expect(history.single.presetVersionId, presets.first.version.id);
    expect(history.single.utcOffset, const Duration(hours: 9));
  });

  test('v5 to v6 mixes new cards in creation order in existing presets', () async {
    final schema = await verifier.schemaAt(5);
    final collection = CollectionId.generate();
    final preset = PresetId.generate();
    final version = PresetVersionId.generate();
    const hlc = '019a2f0c8a00-0000-0123456789abcdef';

    final raw = schema.rawDatabase;
    raw.execute(
      'INSERT INTO collections (id, name, default_preset_id, day_start, hlc) '
      'VALUES (?, ?, ?, 180, ?)',
      [
        collectionIdConverter.toSql(collection),
        'Japanese',
        presetIdConverter.toSql(preset),
        hlc,
      ],
    );
    raw.execute(
      'INSERT INTO presets (id, collection_id, name, current_version_id, hlc) '
      "VALUES (?, ?, 'Default', ?, ?)",
      [
        presetIdConverter.toSql(preset),
        collectionIdConverter.toSql(collection),
        presetVersionIdConverter.toSql(version),
        hlc,
      ],
    );
    raw.execute(
      'INSERT INTO preset_versions (id, preset_id, scheduler_id, '
      'scheduler_config, burn_threshold_days, leech_threshold, '
      'new_cards_per_day, reviews_per_day, hlc) '
      "VALUES (?, ?, 'memuki.steps-sm2', '{\"fuzz\":false}', NULL, 4, 20, "
      '200, ?)',
      [
        presetVersionIdConverter.toSql(version),
        presetIdConverter.toSql(preset),
        hlc,
      ],
    );

    final v6 = MemukiDatabase(schema.newConnection(), replayHistory: replay);
    addTearDown(v6.close);
    await verifier.migrateAndValidate(v6, 6);
    // The rebuilt table keeps its append-only trigger.
    await expectLater(
      v6.customStatement('UPDATE preset_versions SET reviews_per_day = 1'),
      throwsA(anything),
    );
    // Read through the repositories after upgrading to the current version,
    // since they use the current tables. Opening turned foreign keys on for
    // the shared connection; upgrades run with them off.
    await v6.customStatement('PRAGMA foreign_keys = OFF');
    final db = MemukiDatabase(schema.newConnection(), replayHistory: replay);
    addTearDown(db.close);

    expect(
      (await Repositories(db).presets.preset(preset))!.version,
      PresetVersion(
        id: version,
        schedulerConfig: {'fuzz': false},
        burnThreshold: null,
        leechThreshold: 4,
        newCardsPerDay: 20,
        reviewsPerDay: 200,
      ),
    );
  });

  group('from v6', () {
    final collection = CollectionId.generate();
    final preset = PresetId.generate();
    final version = PresetVersionId.generate();
    final deck = DeckId.generate();
    final noteType = NoteTypeId.generate();
    final template = StudyCardTemplateId.generate();
    const hlc = '019a2f0c8a00-0000-0123456789abcdef';
    // 21:00 on 29 October in UTC+9.
    final start = DateTime.utc(2026, 10, 29, 12);

    /// A database at [schemaVersion] (6 or later) with a collection, a deck,
    /// and a note type.
    Future<InitializedSchema> seeded([int schemaVersion = 6]) async {
      final schema = await verifier.schemaAt(schemaVersion);
      final raw = schema.rawDatabase;
      raw.execute(
        'INSERT INTO collections (id, name, default_preset_id, day_start, '
        'hlc) VALUES (?, ?, ?, 180, ?)',
        [
          collectionIdConverter.toSql(collection),
          'Japanese',
          presetIdConverter.toSql(preset),
          hlc,
        ],
      );
      raw.execute(
        'INSERT INTO presets (id, collection_id, name, current_version_id, '
        "hlc) VALUES (?, ?, 'Default', ?, ?)",
        [
          presetIdConverter.toSql(preset),
          collectionIdConverter.toSql(collection),
          presetVersionIdConverter.toSql(version),
          hlc,
        ],
      );
      raw.execute(
        'INSERT INTO preset_versions (id, preset_id, scheduler_id, '
        'scheduler_config, burn_threshold_days, leech_threshold, '
        'new_cards_per_day, reviews_per_day, new_card_mix, new_card_order, '
        "hlc) VALUES (?, ?, 'memuki.steps-sm2', '{}', 365, 8, 50, 500, "
        "'mixed', 'created', ?)",
        [
          presetVersionIdConverter.toSql(version),
          presetIdConverter.toSql(preset),
          hlc,
        ],
      );
      raw.execute(
        'INSERT INTO decks (id, collection_id, name, hlc) VALUES (?, ?, ?, ?)',
        [
          deckIdConverter.toSql(deck),
          collectionIdConverter.toSql(collection),
          'Vocab',
          hlc,
        ],
      );
      raw.execute(
        'INSERT INTO note_types (id, collection_id, name, hlc) '
        'VALUES (?, ?, ?, ?)',
        [
          noteTypeIdConverter.toSql(noteType),
          collectionIdConverter.toSql(collection),
          'Basic',
          hlc,
        ],
      );
      raw.execute(
        'INSERT INTO study_card_templates (id, note_type_id, position, name, '
        'hlc) VALUES (?, ?, 0, ?, ?)',
        [
          studyCardTemplateIdConverter.toSql(template),
          noteTypeIdConverter.toSql(noteType),
          'Card 1',
          hlc,
        ],
      );
      return schema;
    }

    StudyCardId addCard(InitializedSchema schema) {
      final note = NoteId.generate();
      final card = StudyCardId.derive(note, template);
      schema.rawDatabase
        ..execute(
          'INSERT INTO notes (id, collection_id, note_type_id, hlc) '
          'VALUES (?, ?, ?, ?)',
          [
            noteIdConverter.toSql(note),
            collectionIdConverter.toSql(collection),
            noteTypeIdConverter.toSql(noteType),
            hlc,
          ],
        )
        ..execute(
          'INSERT INTO study_cards '
          '(id, collection_id, note_id, template_id, deck_id, hlc) '
          'VALUES (?, ?, ?, ?, ?, ?)',
          [
            studyCardIdConverter.toSql(card),
            collectionIdConverter.toSql(collection),
            noteIdConverter.toSql(note),
            studyCardTemplateIdConverter.toSql(template),
            deckIdConverter.toSql(deck),
            hlc,
          ],
        );
      return card;
    }

    var minute = 0;
    ReviewEventId addEvent(
      InitializedSchema schema,
      StudyCardId card,
      String kind, {
      String? grade,
      ReviewEventId? undoes,
      String schedulerId = 'memuki.steps-sm2',
    }) {
      final id = ReviewEventId.generate();
      schema.rawDatabase.execute(
        'INSERT INTO review_events (id, study_card_id, kind, at, utc_offset, '
        'grade, undone_event_id, scheduler_id, scheduler_version, '
        'preset_version_id, hlc) VALUES (?, ?, ?, ?, 540, ?, ?, ?, 1, ?, ?)',
        [
          reviewEventIdConverter.toSql(id),
          studyCardIdConverter.toSql(card),
          kind,
          start.add(Duration(minutes: minute++)).millisecondsSinceEpoch,
          grade,
          if (undoes == null) null else reviewEventIdConverter.toSql(undoes),
          schedulerId,
          presetVersionIdConverter.toSql(version),
          hlc,
        ],
      );
      return id;
    }

    test('v6 to v7 records the state each event found its card in', () async {
      final schema = await seeded();
      final learned = addCard(schema);
      final first = addEvent(schema, learned, 'review', grade: 'good');
      final second = addEvent(schema, learned, 'review', grade: 'good');
      final undo = addEvent(schema, learned, 'undo', undoes: second);
      final easy = addEvent(schema, learned, 'review', grade: 'easy');
      final burned = addCard(schema);
      final burn = addEvent(schema, burned, 'burn');
      final unburn = addEvent(schema, burned, 'unburn');
      // An unknown scheduler falls back to the preset's latest one.
      final lapse = addEvent(
        schema,
        burned,
        'review',
        grade: 'again',
        schedulerId: 'sm2',
      );
      final after = addEvent(schema, burned, 'review', grade: 'good');

      final db = MemukiDatabase(schema.newConnection(), replayHistory: replay);
      addTearDown(db.close);
      await verifier.migrateAndValidate(db, 7);

      final states = {
        for (final event in [
          ...await Repositories(db).reviews.history(learned),
          ...await Repositories(db).reviews.history(burned),
        ])
          event.id: event.stateBefore,
      };
      expect(states, {
        first: StudyCardState.newCard,
        second: StudyCardState.learning,
        // The state after both reviews, before the undo.
        undo: StudyCardState.learning,
        easy: StudyCardState.learning,
        burn: StudyCardState.newCard,
        unburn: StudyCardState.burned,
        lapse: StudyCardState.review,
        after: StudyCardState.relearning,
      });
      // The rebuilt table keeps its append-only trigger.
      await expectLater(
        db.customStatement("UPDATE review_events SET state_before = 'review'"),
        throwsA(anything),
      );
    });

    test('v6 to v7 fails without a replay function when there are events, '
        'and changes nothing', () async {
      final schema = await seeded();
      addEvent(schema, addCard(schema), 'review', grade: 'good');
      final db = MemukiDatabase(schema.newConnection());
      addTearDown(db.close);
      await expectLater(
        db.ensureOpen(),
        throwsA(isA<DatabaseMigrationException>()),
      );
      final columns = schema.rawDatabase.select(
        "SELECT name FROM pragma_table_info('review_events')",
      );
      expect(columns.map((r) => r['name']), isNot(contains('state_before')));
      expect(
        schema.rawDatabase.select('PRAGMA user_version').single.values.single,
        6,
      );
    });

    test('v6 to v7 needs no replay function without events', () async {
      final schema = await seeded();
      addCard(schema);
      final db = MemukiDatabase(schema.newConnection());
      addTearDown(db.close);
      await verifier.migrateAndValidate(db, 7);
    });

    test('v7 to v8 leaves cards unsuspended and presets burying '
        'siblings', () async {
      final schema = await seeded(7);
      final card = addCard(schema);

      final db = MemukiDatabase(schema.newConnection());
      addTearDown(db.close);
      await verifier.migrateAndValidate(db, 8);

      final repos = Repositories(db);
      final migrated = (await repos.cards.card(card))!;
      expect(migrated.suspended, isFalse);
      expect(migrated.buriedUntil, isNull);
      final settings = (await repos.presets.preset(preset))!.version;
      expect(settings.buryNewSiblings, isTrue);
      expect(settings.buryReviewSiblings, isTrue);
    });
  });
}

String _identity(String value) => value;
